static const BoxSpan *const box_layers[]={box_0,box_1,box_2,box_3,box_4,box_5,box_6,box_7,box_8,box_9,box_10,box_11,box_12,box_13,box_14,box_15};
static const unsigned box_sizes[]={sizeof(box_0)/sizeof(BoxSpan),sizeof(box_1)/sizeof(BoxSpan),sizeof(box_2)/sizeof(BoxSpan),sizeof(box_3)/sizeof(BoxSpan),sizeof(box_4)/sizeof(BoxSpan),sizeof(box_5)/sizeof(BoxSpan),sizeof(box_6)/sizeof(BoxSpan),sizeof(box_7)/sizeof(BoxSpan),sizeof(box_8)/sizeof(BoxSpan),sizeof(box_9)/sizeof(BoxSpan),sizeof(box_10)/sizeof(BoxSpan),sizeof(box_11)/sizeof(BoxSpan),sizeof(box_12)/sizeof(BoxSpan),sizeof(box_13)/sizeof(BoxSpan),sizeof(box_14)/sizeof(BoxSpan),sizeof(box_15)/sizeof(BoxSpan)};
static void box_layer(const MemoriesModHost *h,int layer,int x,int y,int w,int ht,int alpha,int offset,int clip) {
unsigned i;const BoxSpan *p=box_layers[layer];for(i=0;i<box_sizes[layer];i++){
int yy=p[i].y+offset,a=x+p[i].x*w/160,b=y+yy*ht/300;
int c=x+(p[i].x+p[i].n)*w/160,d=y+(yy+1)*ht/300;
if(clip && yy>=132)continue;
if(c>a&&d>b)canvas_fill(h,a,b,c-a,d-b,p[i].rgb,p[i].a*alpha/255);}}
static void box_draw(const MemoriesModHost *h,int index,int x,int y,int w,int ht,int t) {
int alpha=t*255/20;if(alpha>255)alpha=255;
box_layer(h,index*4,x,y,w,ht,255-alpha,0,0);
if(t){box_layer(h,index*4+1,x,y,w,ht,alpha,0,0);
box_layer(h,index*4+2,x,y,w,ht,alpha,110-t*4,1);
box_layer(h,index*4+3,x,y,w,ht,alpha,0,0);}}
